PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS inventory_items(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,dba_id TEXT NOT NULL,sku TEXT NOT NULL,name TEXT NOT NULL,category TEXT,unit TEXT NOT NULL DEFAULT 'each',reorder_level_milli INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'active',created_by_user_id TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(organization_id,dba_id,sku),CHECK(reorder_level_milli>=0),CHECK(status IN ('active','inactive','archived')));
CREATE INDEX IF NOT EXISTS idx_inventory_items_scope ON inventory_items(organization_id,dba_id,status,category,sku);
CREATE TABLE IF NOT EXISTS inventory_locations(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,dba_id TEXT NOT NULL,code TEXT NOT NULL,name TEXT NOT NULL,location_type TEXT NOT NULL DEFAULT 'warehouse',address TEXT,status TEXT NOT NULL DEFAULT 'active',created_by_user_id TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(organization_id,dba_id,code),CHECK(location_type IN ('warehouse','store','vehicle','room','virtual','other')),CHECK(status IN ('active','inactive')));
CREATE INDEX IF NOT EXISTS idx_inventory_locations_scope ON inventory_locations(organization_id,dba_id,status,name);
CREATE TABLE IF NOT EXISTS inventory_movements(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,dba_id TEXT NOT NULL,item_id TEXT NOT NULL,location_id TEXT NOT NULL,movement_type TEXT NOT NULL,quantity_milli INTEGER NOT NULL,reference_type TEXT,reference_id TEXT,reference TEXT,notes TEXT,transfer_group_id TEXT,created_by_user_id TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(item_id) REFERENCES inventory_items(id) ON DELETE RESTRICT,FOREIGN KEY(location_id) REFERENCES inventory_locations(id) ON DELETE RESTRICT,CHECK(movement_type IN ('receipt','issue','adjustment','transfer_in','transfer_out')),CHECK(quantity_milli!=0));
CREATE INDEX IF NOT EXISTS idx_inventory_movements_scope ON inventory_movements(organization_id,dba_id,item_id,location_id,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_inventory_movements_transfer ON inventory_movements(transfer_group_id);
CREATE TABLE IF NOT EXISTS inventory_counts(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,dba_id TEXT NOT NULL,location_id TEXT NOT NULL,count_date TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft',notes TEXT,completed_at TEXT,created_by_user_id TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(location_id) REFERENCES inventory_locations(id) ON DELETE RESTRICT,CHECK(status IN ('draft','completed','void')));
CREATE TABLE IF NOT EXISTS inventory_count_lines(id TEXT PRIMARY KEY,count_id TEXT NOT NULL,item_id TEXT NOT NULL,system_quantity_milli INTEGER NOT NULL,counted_quantity_milli INTEGER NOT NULL,variance_milli INTEGER NOT NULL,adjustment_movement_id TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(count_id) REFERENCES inventory_counts(id) ON DELETE CASCADE,FOREIGN KEY(item_id) REFERENCES inventory_items(id) ON DELETE RESTRICT,FOREIGN KEY(adjustment_movement_id) REFERENCES inventory_movements(id) ON DELETE SET NULL,UNIQUE(count_id,item_id));
CREATE INDEX IF NOT EXISTS idx_inventory_count_lines_count ON inventory_count_lines(count_id,item_id);
